<div class="form-modal" id="bookModal"><div class="modal-box"><div class="modal-head"><div><div class="kicker">Booking servis</div><h2 style="font-size:25px;margin-bottom:4px">Ceritakan motormu.</h2></div><button class="close" onclick="closeBooking()">×</button></div><p class="sub" style="margin-bottom:18px">Masuk terlebih dahulu agar booking tersimpan ke akunmu.</p><div class="notice">🔐 Untuk keamanan, formulir booking lengkap akan tersedia setelah login atau registrasi.</div><div class="form-grid"><div class="field"><label>Merek motor</label><select id="brand"><option>Honda</option><option>Yamaha</option><option>Suzuki</option><option>Kawasaki</option><option>Vespa</option></select></div><div class="field"><label>Tipe motor</label><select id="model"><option>Vario 160</option><option>Vario 125</option><option>Beat</option><option>PCX</option></select></div><div class="field"><label>Nomor plat</label><input placeholder="Contoh: BK 1234 ABC"></div><div class="field"><label>Pilih paket servis</label><select><option>Servis berkala</option><option>Servis CVT</option><option>Paket lengkap</option><option>Tune-up mesin</option></select></div><div class="field"><label>Tanggal</label><input type="date" id="date"></div><div class="field"><label>Preferensi mekanik</label><select><option>Bebas / rekomendasi</option><option>Budi — Senior</option><option>Andi — Engine</option><option>Rizky — CVT</option></select></div><div class="field full"><label>Keluhan motor</label><textarea rows="3" placeholder="Ceritakan kendala atau layanan yang dibutuhkan..."></textarea></div></div><div style="display:flex;gap:10px;margin-top:18px"><a class="btn primary" style="flex:1" href="{{ route('login') }}">Login untuk lanjut →</a><a class="btn ghost" href="{{ route('register') }}">Daftar</a></div></div></div>
<script>const menu=document.getElementById('menu');document.getElementById('hamb').addEventListener('click',()=>menu.classList.toggle('open'));document.addEventListener('click',e=>{if(!e.target.closest('#hamb')&&!e.target.closest('#menu'))menu.classList.remove('open')});function bookingAction(){document.getElementById('bookModal').classList.add('show');document.body.style.overflow='hidden'}function closeBooking(){document.getElementById('bookModal').classList.remove('show');document.body.style.overflow=''}document.getElementById('bookModal').addEventListener('click',e=>{if(e.target.id==='bookModal')closeBooking()});function buyAction(product){if(confirm('Untuk membeli '+product+', kamu perlu login terlebih dahulu. Buka halaman login?'))window.location.href='{{ route('login') }}'}const d=document.getElementById('date');if(d)d.min=new Date().toISOString().split('T')[0];</script></body></html>
